+  const fields: string[] = [];
+  let current = "";
+  let inQuotes = false;
+  let i = 0;
+  let justEndedRow = false;
+
+  while (i < input.length) {
+    const ch = input[i];
+
+    if (ch === '"') {
+      if (inQuotes && i + 1 < input.length && input[i + 1] === '"') {
+        // Escaped quote: "" -> "
+        current += '"';
+        i += 2;
+        continue;
       }
