+      justEndedRow = false;
+      continue;
     }
-    rows.push(fields);
+
+    if ((ch === "\n" || ch === "\r") && !inQuotes) {
+      // Row separator (handle both \n and \r\n)
+      fields.push(current);
+      rows.push([...fields]); // Copy fields array
+      fields.length = 0; // Clear array for reuse
+      current = "";
+      justEndedRow = true;
